# Capability strategies

```ghost
control CapabilityStrategies {
  sensor moisture?: Percent;
  input scheduled: Bool;
  output pump: Bool;
  adapt irrigation_policy {
    strategy WithMoisture priority 100 match (moisture: sensor<Percent>) {
      let request = case moisture { ok(value) => scheduled && value < 30%; fault(_) => false; };
      pump <- request;
    }
    strategy Baseline priority 0 match always { pump <- scheduled; }
  }
}
```
